// One road-space camera for ground, curbs, facades, traffic and the player.
const facadeSheet=new Image(),pursuerSheet=new Image();let facadesReady=false,pursuersReady=false;
facadeSheet.onload=()=>facadesReady=true;facadeSheet.src='assets/saigon-facades.png';pursuerSheet.onload=()=>pursuersReady=true;pursuerSheet.src='assets/chase-team.png';
let chaseLastHit=-100,chaseCount=0,chaseBuffer,chaseSource;
const chaseAudio=new Audio('assets/chay-di.mp3');chaseAudio.preload='auto';
const chaseBytes=fetch('assets/chay-di.mp3').then(r=>r.arrayBuffer()).catch(()=>null);
const worldStart=start,worldFinish=finish,worldRoadHit=registerRoadHit,worldResize=resize,worldRetry=retryBoss,oldProject=project;
function stopChase(){if(chaseSource){try{chaseSource.stop()}catch{}chaseSource=null}chaseAudio.pause()}
function prepareChase(){if(!audio||chaseBuffer)return;chaseBytes.then(b=>b&&audio.decodeAudioData(b.slice(0))).then(b=>{chaseBuffer=b}).catch(()=>{})}
function playChase(){stopChase();if(!sound)return;if(audio&&chaseBuffer){chaseSource=audio.createBufferSource();chaseSource.buffer=chaseBuffer;chaseSource.connect(audio.destination);chaseSource.start()}else{chaseAudio.currentTime=0;chaseAudio.play().catch(()=>{})}}
start=function(){stopChase();chaseLastHit=-100;chaseCount=0;document.body.classList?.add('is-playing');worldStart();prepareChase();resize()};
finish=function(){stopChase();document.body.classList?.remove('is-playing');worldFinish()};
retryBoss=function(){document.body.classList?.add('is-playing');worldRetry();resize()};
registerRoadHit=function(){const before=roadHits;worldRoadHit();if(roadHits>before){chaseLastHit=elapsed;chaseCount++;pressure=Math.min(.95,.28+roadHits*.15);playChase()}};
const oldSoundClick=$('sound').onclick;$('sound').onclick=()=>{oldSoundClick();if(!sound)stopChase();else prepareChase()};
const oldPauseClick=$('pause').onclick;$('pause').onclick=()=>{oldPauseClick();if(paused)stopChase()};
resize=function(){if(canvas.clientWidth<=700&&document.body.classList?.contains('is-playing')){const top=canvas.getBoundingClientRect().top,controls=$('controls').getBoundingClientRect?.().height||90,vh=globalThis.visualViewport?.height||globalThis.innerHeight||800;canvas.style.setProperty?.('height',Math.max(220,vh-top-controls-12)+'px','important')}const r=canvas.getBoundingClientRect(),dpr=Math.min(2,globalThis.devicePixelRatio||1);canvas.width=Math.round(r.width*dpr);canvas.height=Math.round(r.height*dpr);ctx.setTransform(dpr,0,0,dpr,0,0)};
globalThis.visualViewport?.addEventListener('resize',()=>resize());
function heroSize(){return Math.min(185,canvas.clientHeight*.29,canvas.clientWidth*.34)}
function streetPoint(x,Z,height=0,w=canvas.clientWidth,h=canvas.clientHeight){const s=12/Math.max(2,Z);return{x:w/2+x*w*.42*s,y:h*.24+h*.54*s-height*h*.09*s,s}}
function objectDepth(z){return Math.max(2,12+(z-.1)*70)}
project=function(l,z,w,h){if(mode===2)return oldProject(l,z,w,h);const p=streetPoint((l-1)*.55,objectDepth(z),0,w,h);return{...p,p:p.s}};
function facadeSegments(){const out=[],segment=14,travel=worldDistance*.40;for(let i=0;i<13;i++){const a=((i*segment-travel)%(segment*13)+segment*13)%(segment*13)-segment,b=a+segment;if(b<4||a>140)continue;for(const side of [-1,1])out.push({side,index:i,near:Math.max(3.5,a),far:b,rawNear:a,height:8.8+(i%3)*1.4})}return out.sort((a,b)=>b.far-a.far)}
function imageTriangle(img,source,dest){const [a,b,c]=source,[p,q,r]=dest,den=a.x*(b.y-c.y)+b.x*(c.y-a.y)+c.x*(a.y-b.y);if(Math.abs(den)<.0001)return;const A=(p.x*(b.y-c.y)+q.x*(c.y-a.y)+r.x*(a.y-b.y))/den,C=(p.x*(c.x-b.x)+q.x*(a.x-c.x)+r.x*(b.x-a.x))/den,E=(p.x*(b.x*c.y-c.x*b.y)+q.x*(c.x*a.y-a.x*c.y)+r.x*(a.x*b.y-b.x*a.y))/den,B=(p.y*(b.y-c.y)+q.y*(c.y-a.y)+r.y*(a.y-b.y))/den,D=(p.y*(c.x-b.x)+q.y*(a.x-c.x)+r.y*(b.x-a.x))/den,F=(p.y*(b.x*c.y-c.x*b.y)+q.y*(c.x*a.y-a.x*c.y)+r.y*(a.x*b.y-b.x*a.y))/den;ctx.save();ctx.beginPath();ctx.moveTo(p.x,p.y);ctx.lineTo(q.x,q.y);ctx.lineTo(r.x,r.y);ctx.closePath();ctx.clip();ctx.transform(A,B,C,D,E,F);ctx.drawImage(img,0,0);ctx.restore()}
function facadeQuad(source,quad){imageTriangle(facadeSheet,[source[0],source[1],source[2]],[quad[0],quad[1],quad[2]]);imageTriangle(facadeSheet,[source[0],source[2],source[3]],[quad[0],quad[2],quad[3]])}
function renderFacades(){if(!facadesReady)return;const cw=facadeSheet.width/4,ch=facadeSheet.height;for(const b of facadeSegments()){const cell=b.index%4,x=b.side*1.5,steps=b.near<25?6:b.near<60?3:1;for(let i=0;i<steps;i++){const z0=b.near+(b.far-b.near)*i/steps,z1=b.near+(b.far-b.near)*(i+1)/steps,u0=(z0-b.rawNear)/14,u1=(z1-b.rawNear)/14,near=streetPoint(x,z0),far=streetPoint(x,z1),topFar=streetPoint(x,z1,b.height),topNear=streetPoint(x,z0,b.height);const sx=cell*cw;facadeQuad([{x:sx+u0*cw,y:ch},{x:sx+u1*cw,y:ch},{x:sx+u1*cw,y:0},{x:sx+u0*cw,y:0}],[near,far,topFar,topNear])}}}
function curbPolygon(x0,x1,color){const a=streetPoint(x0,3),b=streetPoint(x1,3),c=streetPoint(x1,160),d=streetPoint(x0,160);poly([[a.x,a.y],[b.x,b.y],[c.x,c.y],[d.x,d.y]],color)}
function drawSidewalkProps(){const props=[];for(let i=0;i<8;i++){const Z=((i*20-worldDistance*.40)%160+160)%160+4;for(const side of [-1,1])props.push({side,Z,index:i})}props.sort((a,b)=>b.Z-a.Z);for(const o of props){const p=streetPoint(o.side*1.22,o.Z),s=p.s,H=canvas.clientHeight;ctx.save();ctx.translate(p.x,p.y);ctx.scale(s,s);const lamp=H*.27;ctx.strokeStyle='#315159';ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(0,0);ctx.lineTo(0,-lamp);ctx.quadraticCurveTo(0,-lamp-12,-o.side*16,-lamp-12);ctx.stroke();ctx.fillStyle=rain>.3?'#ffe6a8':'#e6d5ab';ctx.beginPath();ctx.ellipse(-o.side*16,-lamp-8,9,5,0,0,7);ctx.fill();ctx.restore()}}
function worldTraffic(cell,height){if(!trafficReady)return;const cw=trafficSheet.width/4,ch=trafficSheet.height,width=height*cw/ch;ctx.drawImage(trafficSheet,cell*cw,0,cw,ch,-width/2,-height,width,height)}
function drawPursuers(){if(!pursuersReady)return;const w=canvas.clientWidth,h=canvas.clientHeight,size=heroSize()*.88,burst=Math.max(0,1-(elapsed-chaseLastHit)/3),advance=Math.min(1,roadHits*.16+burst*.32),foot=h+size*.8-size*advance,cw=pursuerSheet.width/3,ch=pursuerSheet.height/2,row=Math.floor(elapsed*7)%2;for(let i=0;i<3;i++){const x=w*(.14+i*.36),width=size*cw/ch;ctx.save();ctx.globalAlpha=.85;ctx.drawImage(pursuerSheet,i*cw,row*ch,cw,ch,x-width/2,foot-size,width,size);ctx.restore();if(advance>.2)text(['SẾP','DEADLINE','BẢN KẾ HOẠCH'][i],x,foot-size-8,Math.max(8,Math.min(10,w*.021)),'#ffc4ac')}}
drawLivingStreet=function(){const w=canvas.clientWidth,h=canvas.clientHeight,H=heroSize();ctx.save();if(hitShake>0)ctx.translate(Math.sin(elapsed*65)*hitShake*9,0);weatherPanel(0,w,h);if(rain>0)weatherPanel(1,w,h,rain);if(flood>0)weatherPanel(2,w,h,flood);
const ground=ctx.createLinearGradient(0,h*.24,0,h);ground.addColorStop(0,flood>.5?'#456f81':rain>.4?'#758590':'#a8afb0');ground.addColorStop(.6,flood>.5?'#2c6078':rain>.4?'#4d6373':'#85969c');ground.addColorStop(1,flood>.5?'#1d4a63':rain>.4?'#344f65':'#6c818c');curbPolygon(-1,1,ground);curbPolygon(-1.50,-1.0,rain>.4?'#6c7479':'#d4c4a8');curbPolygon(1.0,1.50,rain>.4?'#6c7479':'#d4c4a8');
// Road texture and lane marks are attached to the same advancing world depth as buildings.
for(let i=0;i<38;i++){const Z=((i*4-worldDistance*.40)%152+152)%152+3;if(flood>.5){const a=streetPoint(-.98,Z),b=streetPoint(.98,Z);ctx.strokeStyle='#afdae14d';ctx.lineWidth=1+a.s*.6;ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.quadraticCurveTo(w/2,a.y+Math.sin(elapsed*3+i)*3,b.x,b.y);ctx.stroke()}else{for(const x of [-.275,.275]){const a=streetPoint(x,Z),b=streetPoint(x,Z+1.25);ctx.strokeStyle=rain>.5?'#e3e6df77':'#f6edcbb5';ctx.lineWidth=Math.max(1,a.s*2);ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.stroke()}for(let j=0;j<3;j++){const p=streetPoint(Math.sin(i*33+j*19)*.9,Z);ctx.fillStyle='#d9e1df18';ctx.fillRect(p.x,p.y,Math.max(1,p.s),Math.max(1,p.s*.7))}}}
for(const x of [-1,1]){const a=streetPoint(x,3),b=streetPoint(x,160);ctx.strokeStyle=rain>.3?'#aebec1':'#f0d8ab';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.stroke()}renderFacades();drawSidewalkProps();
const items=objects.filter(o=>o.z>-.04).map(o=>({kind:'obstacle',Z:objectDepth(o.z),o}));if(mode===0)for(let i=0;i<2;i++){const Z=((i*60-worldDistance*.22)%120+120)%120+7;items.push({kind:'rider',Z,side:i%2?-1:1})}items.sort((a,b)=>b.Z-a.Z);
for(const item of items){const p=streetPoint(item.kind==='rider'?item.side*.85:(item.o.lane-1)*.55,item.Z);ctx.save();ctx.translate(p.x,p.y);ctx.scale(p.s,p.s);if(item.kind==='rider')worldTraffic(3,H*1.06);else if(mode===1)drawWaterObstacle(item.o.type);else if(item.o.type===3)proceduralRoadObstacle(3);else worldTraffic(item.o.type===1?0:item.o.type===2?1:2,H*(item.o.type===1?1.7:item.o.type===2?1.15:.65));ctx.restore()}
drawPursuers();const p=project(visualLane,.1,w,h);ctx.globalAlpha=invincible>0&&Math.floor(elapsed*12)%2===0?.5:1;ctx.fillStyle='#102a3a33';ctx.beginPath();ctx.ellipse(p.x,p.y+6,H*.18,6,0,0,7);ctx.fill();if(mode===1){ctx.save();ctx.translate(p.x,p.y+Math.sin(elapsed*4)*2);ctx.scale(H/185,H/185);ctx.rotate(Math.sin(elapsed*3)*.025);poly([[0,24],[-43,-8],[-32,-78],[0,-104],[32,-78],[43,-8]],'#b98c59');poly([[0,12],[-30,-13],[-22,-67],[0,-88],[22,-67],[30,-13]],'#695341');lifeSprite(Math.floor(elapsed*(3+rowPower*3))%4,0,4,165);ctx.restore();ctx.strokeStyle='#c0e3e477';ctx.lineWidth=2;for(let i=0;i<3;i++){ctx.beginPath();ctx.ellipse(p.x,p.y+15+i*9,H*.18+i*8,4+i*2,0,0,Math.PI);ctx.stroke()}}else sprite(Math.floor(elapsed*7)%2,p.x,p.y+8-jump*.6,H);ctx.globalAlpha=1;
if(rain>0){ctx.fillStyle=`rgba(6,17,36,${rain*.3})`;ctx.fillRect(0,0,w,h);ctx.strokeStyle=`rgba(203,226,239,${rain*.7})`;ctx.lineWidth=1;for(let i=0;i<Math.min(140,w*.25)*rain;i++){const x=(i*71+elapsed*210)%w,y=(i*53+elapsed*570)%h;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x-8,y+20);ctx.stroke()}}ctx.restore()};
// Preload/decode from the same user-unlocked AudioContext used by the game.
const worldAct=act;act=function(){worldAct();if(!chaseBuffer)prepareChase()};$('action').onclick=()=>act();
